229	/* A pixel centre exactly on an edge that two polygons share (a 45 degree edge
230	 * through integer vertices passes through pixel centres) belongs to the one
231	 * on its left. Float error of a few millionths in an edge's x can drop it from
232	 * both and leave a hole in a wide arc, so a right edge is inclusive to within
233	 * this much (issue #56). */
234	#define EDGE_SLACK 1e-3f
235	
236	/* Fills a convex polygon whose vertices are in pixel coordinates, where the
237	 * pixel at x, y has its centre at x + 0.5, y + 0.5. A pixel is drawn when its
238	 * centre is inside, the left and top edges excluded and the right and bottom
239	 * edges included. The vertices stay floats: canvas_fill_polygon takes ints,
240	 * which would move the edges of a thin line by up to half a pixel. */
241	static void fill_convex(Canvas *c, const float pts[][2], int n,
242	                        uint16_t colour) {
243	  float ymin = pts[0][1], ymax = ymin;
244	  for (int i = 1; i < n; i++) {
245	    ymin = fminf(ymin, pts[i][1]);
246	    ymax = fmaxf(ymax, pts[i][1]);
247	  }
248	  const wide_t y0 = max_w(0, (wide_t)floorf(ymin));
249	  const wide_t y1 = min_w((wide_t)c->h - 1, (wide_t)ceilf(ymax));
250	  for (wide_t y = y0; y <= y1; y++) {
251	    const float sy = (float)y + 0.5f;
252	    float xl = INFINITY, xr = -INFINITY;
253	    for (int i = 0, j = n - 1; i < n; j = i++) {
254	      const float yi = pts[i][1], yj = pts[j][1];
255	      if ((yi < sy && yj >= sy) || (yj < sy && yi >= sy)) {
256	        const float x = pts[i][0] + (sy - yi) / (yj - yi) * (pts[j][0] - pts[i][0]);
257	        xl = fminf(xl, x);
258	        xr = fmaxf(xr, x);
259	      }
260	    }
261	    if (xl > xr) continue;
262	    fill_box(c, (wide_t)floorf(xl - 0.5f) + 1, y,
263	             (wide_t)floorf(xr - 0.5f + EDGE_SLACK), y, colour);
264	  }
265	}
