268	static float centre_offset(int w) { return (w & 1) ? 0.5f : 0.0f; }
269	
270	static vec2 vertex(int x, int y, int w) {
271	  const float o = centre_offset(w);
272	  return (vec2){(float)x + o, (float)y + o};
