389	void stroke_circle(Canvas *c, const struct XshimGC *gc, int x, int y, unsigned w) {
390	  const int lw = gc->line_width;
391	  const uint16_t colour = (uint16_t)gc->foreground;
392	  g_alpha = gc->alpha;
393	  const float o = centre_offset(lw);
394	  const float radius = (float)w / 2.0f;
395	  const float cx = (float)x + radius + o, cy = (float)y + radius + o;
396	  const float outer = radius + (float)lw / 2.0f;
397	  const float inner = radius - (float)lw / 2.0f;
398	  const wide_t y0 = max_w(0, (wide_t)floorf(cy - outer));
399	  const wide_t y1 = min_w((wide_t)c->h - 1, (wide_t)ceilf(cy + outer));
400	  for (wide_t row = y0; row <= y1; row++) {
401	    const float dy = (float)row + 0.5f - cy;
402	    if (fabsf(dy) >= outer) continue;
403	    const float ho = sqrtf(outer * outer - dy * dy);
404	    const wide_t xo0 = (wide_t)ceilf(cx - ho - 0.5f);
405	    const wide_t xo1 = (wide_t)floorf(cx + ho - 0.5f);
406	    if (inner <= 0.0f || fabsf(dy) >= inner) {
407	      fill_box(c, xo0, row, xo1, row, colour);
408	      continue;
409	    }
410	    const float hi = sqrtf(inner * inner - dy * dy);
411	    const wide_t xi0 = (wide_t)ceilf(cx - hi - 0.5f);
412	    const wide_t xi1 = (wide_t)floorf(cx + hi - 0.5f);
413	    fill_box(c, xo0, row, xi0 - 1, row, colour);
414	    fill_box(c, xi1 + 1, row, xo1, row, colour);
415	  }
416	}
