419	  const float dx = (float)((wide_t)to[0] - from[0]);
420	  const float dy = (float)((wide_t)to[1] - from[1]);
421	  const float len = sqrtf(dx * dx + dy * dy);
422	  return (vec2){dx / len, dy / len};
