425	void stroke_polyline(Canvas *c, const struct XshimGC *gc, const int *xy, int n,
426	                     int closed) {
427	  if (n <= 0) return;
428	  const int w = gc->line_width;
429	  const uint16_t colour = (uint16_t)gc->foreground;
430	  g_alpha = gc->alpha;
431	
432	  int stack_v[2 * 64];
433	  int *v = stack_v;
434	  if (n > 64) {
435	    v = (int *)malloc((size_t)n * 2 * sizeof(int));
436	    if (!v) return;
437	  }
438	  int m = 0;
439	  for (int i = 0; i < n; i++) {
440	    if (m > 0 && xy[2 * i] == v[2 * (m - 1)] && xy[2 * i + 1] == v[2 * (m - 1) + 1])
441	      continue;
442	    v[2 * m] = xy[2 * i];
443	    v[2 * m + 1] = xy[2 * i + 1];
444	    m++;
445	  }
446	  if (closed && m > 1 && v[2 * (m - 1)] == v[0] && v[2 * (m - 1) + 1] == v[1]) m--;
447	
448	  if (m == 1 || (m == 2 && !closed)) {
449	    stroke_segment(c, gc, v[0], v[1], v[2 * (m - 1)], v[2 * (m - 1) + 1]);
450	  } else {
451	    const int nseg = closed ? m : m - 1;
452	    if (g_alpha) open_mask(c);
453	    for (int i = 0; i < nseg; i++) {
454	      const int *a = v + 2 * i, *b = v + 2 * ((i + 1) % m);
455	      const int cap1 = (!closed && i == 0) ? gc->cap_style : STROKE_NO_CAP;
456	      const int cap2 = (!closed && i == nseg - 1) ? gc->cap_style : STROKE_NO_CAP;
457	      if (cap1 == CapRound) disc(c, a[0], a[1], w, colour);
458	      if (cap2 == CapRound) disc(c, b[0], b[1], w, colour);
459	      segment_quad(c, vertex(a[0], a[1], w), vertex(b[0], b[1], w), cap1, cap2, w,
460	                   colour);
461	    }
462	    const int first = closed ? 0 : 1, last = closed ? m : m - 1;
463	    for (int j = first; j < last; j++) {
464	      const int *prev = v + 2 * ((j + m - 1) % m), *at = v + 2 * j;
465	      const int *next = v + 2 * ((j + 1) % m);
466	      join_at(c, at[0], at[1], direction(prev, at), direction(at, next), w,
467	              gc->join_style, colour);
468	    }
469	    close_mask(c, colour);
470	  }
471	  if (v != stack_v) free(v);
472	}
