/* Draft of the integer canvas_fill_ellipse. The old double version stays as
 * the fallback for sizes whose squares do not fit 64 bits and as the test's
 * reference. */

/* Half the width of the row at 2*(yy - cy) == dy2, in the same doubled units:
 * the largest s with s*s*h*h <= w*w*(h*h - dy2*dy2). */
static int64_t ellipse_half_span2(int64_t w, int64_t h, int64_t dy2) {
  const int64_t q = h * h - dy2 * dy2; /* > 0 inside the ellipse */
  const int64_t limit = w * w * q;
  int64_t s = (int64_t)(sqrtf((float)q) * (float)w / (float)h);
  while (s > 0 && s * s * h * h > limit) s--;
  while ((s + 1) * (s + 1) * h * h <= limit) s++;
  return s;
}

