        const int64_t num = (2 * (int64_t)(y - e->ylo) + 1) * e->dx - e->den / 2;
        const int64_t q = floor_div(num, e->den);
        e->col = e->xlo + (int)q;
        e->rem = (int)(num - q * e->den);
